actions.script:
if (System.getProperty('purchase.pricing.qa.disposable') != 'true' || !ec.user.isInGroup('ADMIN')) {
    ec.web.response.setStatus(403); ec.web.sendJsonResponse([denied:true]); return
}
if (ec.entity.find('mantle.party.Party').condition('partyId','PP_QA_A').disableAuthz().count()) {
    ec.web.response.setStatus(409); ec.web.sendJsonResponse([denied:true]); return
}
ec.entity.makeDataLoader().location('component://zenith-erp-purchase/PurchaseRemainingQaFixture.xml').load()
if (ec.message.hasError()) throw new IllegalStateException('Fixture did not load')
ec.entity.find('zenith.erp.base.CompanySettings').condition('organizationPartyId','PP_QA_A')
    .condition('settingKey','CURRENCY_UOM_ID').one().set('settingValue','INR').update()
ec.entity.makeValue('mantle.account.invoice.Invoice').setAll([invoiceId:'PP_QA_GRN_BILL_INR',
    invoiceTypeEnumId:'InvoicePurchase', statusId:'InvoiceApproved', currencyUomId:'INR',
    fromPartyId:'PP_QA_SUPPLIER_A', toPartyId:'PP_QA_A', invoiceDate:ec.user.nowTimestamp,
    invoiceTotal:200G, unpaidTotal:200G]).create()
def demo = ec.entity.find('moqui.security.UserAccount').condition('userId','EX_JOHN_DOE').one()
for (id in ['PP_QA_USER','PP_QA_VIEWER']) {
    def user = ec.entity.find('moqui.security.UserAccount').condition('userId',id).one()
    for (key in ['currentPassword','passwordSalt','passwordHashType','passwordBase64']) user.set(key,demo.get(key))
    user.setAll([disabled:'N',requirePasswordChange:'N']).update()
}
for (org in ['PP_QA_A','PP_QA_B']) {
    ec.entity.makeValue('mantle.party.PartyIdentification').setAll([partyId:org,partyIdTypeEnumId:'PtidOrgCode',idValue:org]).create()
    ec.entity.makeValue('mantle.facility.Facility').setAll([facilityId:org+'_STORE',facilityName:'Disposable receiving store '+org,ownerPartyId:org]).create()
}
ec.web.sendJsonResponse([initialized:true])
